\begin{aligned}
\text{Axioma 1: } & \text{EXPLICAÇÃO} \neq \text{ENUMERAÇÃO} \\
\text{Axioma 2: } & \text{EXPLICAÇÃO} = \text{ESCLARECIMENTO} \\
\text{Axioma 3: } & \text{EXPLICAR} = \text{JUSTIFICAR} = \text{DIZER O MESMO} \neq \text{IDEIA NOVA}
\end{aligned}

\begin{aligned}
\text{Polo Conotativo (Não Literal): } & \text{Sentido Figurado} = \text{Sentido Conotativo} = \text{Relativizar o Significado} = \text{Diverso do Usual} \\
\text{Polo Denotativo (Literal): } & \text{Sentido Real} = \text{Sentido Denotativo} = \text{Sentido Literal} = \text{Sentido do Dicionário}
\end{aligned}

