flowchart TD
  start["Início: Isolar segmento com ponto e vírgula e colocação pronominal"] -- "Examinar corte sintático" --> dec_pv_escopo{"O ponto e vírgula separa termos sintáticos imediatos (S-V ou V-Obj)?"}
  dec_pv_escopo -- "Sim" --> res_pv_erro["Ponto e Vírgula Inválido: Quebra proibida de relação sintática imediata"]
  dec_pv_escopo -- "Não" --> dec_pv_contexto{"Separa orações coordenadas autônomas ou itens de enumeração?"}
  dec_pv_contexto -- "Não" --> res_pv_inadequado["Ponto e Vírgula Inadequado: Ausência de justificativa sintática de coordenação"]
  dec_pv_contexto -- "Sim" --> proc_pv_valido["Ponto e Vírgula Válido: Avançar para análise de colocação pronominal"]
  proc_pv_valido -- "Verificar colocação" --> dec_pronome{"Há pronome oblíquo átono na oração iniciada após o ponto e vírgula?"}
  dec_pronome -- "Não" --> res_sem_pronome["Estrutura Conforme: Pontuação correta sem implicações de colocação pronominal"]
  dec_pronome -- "Sim" --> dec_atrator{"Há palavra atrativa (não, nunca, que, se) logo após o ponto e vírgula?"}
  dec_atrator -- "Não" --> dec_posicao_sem{"Qual a posição do pronome em relação ao verbo inicial?"}
  dec_posicao_sem -- "Próclise (pronome antes do verbo)" --> res_trava_violada["Erro de Colocação: Trava de Próclise violada (proibido iniciar com oblíquo após pausa)"]
  dec_posicao_sem -- "Ênclise (verbo antes do pronome)" --> res_enclise_correta["Colocação Correta: Ênclise obrigatória cumprida após pausa pontuada"]
  dec_atrator -- "Sim" --> dec_virgula_atrator{"A palavra atrativa está isolada por vírgula posterior?"}
  dec_virgula_atrator -- "Sim (com vírgula)" --> res_atrator_isolado["Pausa Anula Atração: Vírgula quebra atração imediata, exigindo ênclise ao verbo"]
  dec_virgula_atrator -- "Não (sem vírgula)" --> res_proclise_obrigatoria["Colocação Correta: Palavra atrativa supera a pausa e exige próclise"]

